package propertyrental.platform.listing.application.mapper;

import org.springframework.stereotype.Component;

import propertyrental.platform.listing.api.dto.request.CreateFacilityRequest;
import propertyrental.platform.listing.api.dto.request.UpdateFacilityRequest;
import propertyrental.platform.listing.api.dto.response.FacilityResponse;
import propertyrental.platform.listing.infrastructure.persistence.entity.FacilityEntity;

@Component
public class FacilityMapper {

    // Build a new entity from a create request (the id is generated by the database)
    public FacilityEntity toEntity(CreateFacilityRequest request) {
        FacilityEntity facility = new FacilityEntity();
        facility.setCode(request.code());
        facility.setName(request.name());

        return facility;
    }

    // Apply an update request to an existing entity in place
    public void updateEntity(FacilityEntity facility, UpdateFacilityRequest request) {
        facility.setCode(request.code());
        facility.setName(request.name());
    }

    // Convert an entity to the response DTO so that the entity is never exposed
    public FacilityResponse toResponse(FacilityEntity facility) {

        return new FacilityResponse(
                facility.getId(),
                facility.getCode(),
                facility.getName()
        );
    }
}